script:
// Client Script ERPNext / Frappe
// DocType: Tache de travail
// Version réécrite et structurée

(function () {
    const DOCTYPE = 'Tache de travail';
    const BOOKING_METHOD = 'get_customer_booking_info';

    const INTERVENTION_ICONS = {
        'Entretien': '🔧 ',
        'Installation': '🔨 ',
        'Réparation': '🧰 ',
        'Livraison': '🚐 ',
        'Visite': '🚗 ',
        'Autre': '☕ '
    };

    const INTERVENTION_DURATIONS = {
        'Entretien': 45,
        'Installation': 105,
        'Réparation': 120,
        'Livraison': 30,
        'Visite': 120,
        'Autre': 120
    };

    frappe.ui.form.on(DOCTYPE, {
        setup(frm) {
            set_link_queries(frm);
        },

        onload(frm) {
            if (frm.doc.starts_on && !frm.doc.ends_on) {
                update_end_time(frm);
            }

            fetch_customer_booking_info(frm);
        },

        validate(frm) {
            update_title_and_color(frm);
        },

        after_save(frm) {
            frappe.set_route('tache-de-travail/view/calendar/Calendrier%20de%20travail');
        },

        custom_choix_du_staff(frm) {
            update_employee_name(frm);
        },

        starts_on(frm) {
            update_end_time(frm);
        },

        custom_type_dintervention(frm) {
            update_end_time(frm);
            clear_address_fields(frm);
        },

        dans_local(frm) {
            clear_address_fields(frm);
        },

        custom_client(frm) {
            clear_address_fields(frm);
            update_customer_phone(frm);
            fetch_customer_booking_info(frm);
        },

        select_address(frm) {
            update_full_address(frm);
        },

        commande_client(frm) {
            create_sales_order_from_task(frm);
        },

        upload_photos(frm) {
            upload_images_to_field(frm, 'liste_photos_avant');
        },

        upload_after(frm) {
            upload_images_to_field(frm, 'liste_photos_apres');
        }
    });

    function set_link_queries(frm) {
        frm.set_query('commande_client', function () {
            return {
                filters: {
                    status: ['!=', 'Cancelled'],
                    customer: ['=', frm.doc.custom_client]
                }
            };
        });

        frm.set_query('select_address', function () {
            if (is_repair_in_local(frm)) {
                return {
                    filters: {
                        address_title: ['=', 'Soukra-Magasin']
                    }
                };
            }

            return {
                filters: {
                    link_doctype: ['=', 'Customer'],
                    link_name: ['=', frm.doc.custom_client]
                }
            };
        });
    }

    function is_repair_in_local(frm) {
        return frm.doc.custom_type_dintervention === 'Réparation' && frm.doc.dans_local === 'Oui';
    }

    function clear_address_fields(frm) {
        frm.set_value('select_address', '');
        frm.set_value('details_adresse', '');
        frm.set_value('google_map', '');
    }

    function get_intervention_duration(type_intervention) {
        return INTERVENTION_DURATIONS[type_intervention] || 120;
    }

    function update_end_time(frm) {
        if (!frm.doc.starts_on) return;

        const start_time = moment(frm.doc.starts_on, 'YYYY-MM-DD HH:mm:ss');

        if (!start_time.isValid()) {
            frappe.msgprint({
                title: __('Erreur'),
                indicator: 'red',
                message: __('La date de début est invalide.')
            });
            return;
        }

        const duration = get_intervention_duration(frm.doc.custom_type_dintervention);
        const end_time = start_time.clone().add(duration, 'minutes');

        frm.set_value('ends_on', end_time.format('YYYY-MM-DD HH:mm:ss'));
    }

    function update_employee_name(frm) {
        if (!frm.doc.custom_choix_du_staff) {
            frm.set_value('custom_employé', '');
            return;
        }

        frappe.db.get_value('Employee', frm.doc.custom_choix_du_staff, 'employee_name')
            .then(function (r) {
                frm.set_value('custom_employé', r.message?.employee_name || '');
            });
    }

    function update_customer_phone(frm) {
        if (!frm.doc.custom_client) {
            frm.set_value('tel', '');
            return;
        }

        frappe.db.get_value('Customer', frm.doc.custom_client, 'custom_liste_telephone')
            .then(function (r) {
                frm.set_value('tel', r.message?.custom_liste_telephone || '');
            });
    }

    function fetch_customer_booking_info(frm) {
        if (!frm.doc.custom_client) {
            frm.dashboard.clear_headline();
            return;
        }

        frappe.call({
            method: BOOKING_METHOD,
            args: {
                customer_name: frm.doc.custom_client,
                task_name: frm.doc.name
            },
            callback: function (r) {
                if (!r.result) return;

                const rendez_vous_O = r.result[0] || [];
                const rendez_vous_C = r.result[1] || [];

                frm.dashboard.clear_headline();

                if (rendez_vous_C.length > 0) {
                    frm.dashboard.set_headline_alert(rendez_vous_C.join('<br>'), 'red');
                    return;
                }

                if (rendez_vous_O.length > 0) {
                    frm.dashboard.set_headline_alert(rendez_vous_O.join('<br>'), 'yellow');
                }
            }
        });
    }

    function update_title_and_color(frm) {
        // Couleur décidée côté serveur (compute_tache_color) — source unique.
        // Ici on ne compose que le titre.
        const intervention_icon = INTERVENTION_ICONS[frm.doc.custom_type_dintervention] || '☕ ';
        const intervention_type = frm.doc.custom_type_dintervention || '';
        const client = frm.doc.custom_client || '';
        const employee = frm.doc.custom_employé || '';
        const secteur = frm.doc.secteur || '';

        let titre = `${intervention_icon}${intervention_type}: Client: ${client}\n${employee}`;

        if (frm.doc.status === 'Cancelled') {
            titre = `Annulé!!!\n${titre}`;
        } else if (frm.doc.status === 'Completed') {
            titre = `terminé!!!\n${titre}`;
        } else {
            titre = `${secteur}\n${titre}`;
        }

        frm.set_value('titre', titre);
    }

    function update_full_address(frm) {
        if (!frm.doc.select_address) {
            frm.set_value('details_adresse', '');
            frm.set_value('google_map', '');
            return;
        }

        frappe.db.get_value('Address', frm.doc.select_address, [
            'address_line1',
            'address_line2',
            'city',
            'pincode',
            'state',
            'country',
            'custom_lien_google_map'
        ]).then(function (r) {
            const address = r.message || {};
            const lines = [];

            if (address.address_line1) lines.push(address.address_line1);
            if (address.address_line2) lines.push(address.address_line2);
            if (address.city) lines.push(address.city);

            const region = [
                address.pincode,
                address.state,
                address.country
            ].filter(Boolean).join(', ');

            if (region) lines.push(region);

            frm.set_value('details_adresse', lines.join('\n'));
            frm.set_value('google_map', address.custom_lien_google_map || '');
        });
    }

    function create_sales_order_from_task(frm) {
        // Dans ton script original, la création se déclenche seulement si commande_client est vide.
        if (frm.doc.commande_client) return;

        if (!frm.doc.custom_client) {
            frappe.msgprint({
                title: __('Client requis'),
                indicator: 'orange',
                message: __('Veuillez sélectionner un client avant de créer la commande client.')
            });
            return;
        }

        frappe.model.with_doctype('Sales Order', function () {
            const sales_order_doc = frappe.model.get_new_doc('Sales Order');

            sales_order_doc.customer = frm.doc.custom_client;
            sales_order_doc.delivery_date = frm.doc.starts_on;

            const is_installation_or_livraison = [
                'Installation',
                'Livraison'
            ].includes(frm.doc.custom_type_dintervention);

            if (!is_installation_or_livraison) {
                sales_order_doc.custom_type_de_transaction = 'Vente directe sans BL et Facture';
                sales_order_doc.taxes_and_charges = 'Vente Standard Sans Timbre Fiscale - A&S';

                if (frm.doc.custom_choix_du_staff) {
                    frappe.db.get_value('Employee', frm.doc.custom_choix_du_staff, 'custom_warehouse')
                        .then(function (r) {
                            if (r.message?.custom_warehouse) {
                                sales_order_doc.set_warehouse = r.message.custom_warehouse;
                            }

                            frappe.set_route('Form', 'Sales Order', sales_order_doc.name);
                        });
                    return;
                }
            }

            frappe.set_route('Form', 'Sales Order', sales_order_doc.name);
        });
    }

    function upload_images_to_field(frm, target_field) {
        const uploaded_file_urls = [];

        new frappe.ui.FileUploader({
            allow_multiple: true,
            folder: 'Home',
            restrictions: {
                allowed_file_types: ['image/*']
            },
            on_success: function (file_data) {
                if (!file_data) {
                    frappe.msgprint(__('Upload failed. Please try again.'));
                    return;
                }

                const files = Array.isArray(file_data) ? file_data : [file_data];

                Promise.all(files.map(function (file) {
                    return new Promise(function (resolve, reject) {
                        frappe.call({
                            method: 'frappe.client.insert',
                            args: {
                                doc: {
                                    doctype: 'File',
                                    file_url: file.file_url,
                                    attached_to_doctype: frm.doctype,
                                    attached_to_name: frm.docname
                                }
                            },
                            callback: function (response) {
                                if (response && response.message) {
                                    uploaded_file_urls.push(`📁 "${file.file_url}"`);
                                    resolve();
                                } else {
                                    reject(`Upload failed: ${file.file_url}`);
                                }
                            }
                        });
                    });
                }))
                    .then(function () {
                        const existing_value = frm.doc[target_field] || '';
                        const new_value = uploaded_file_urls.join('\n');
                        const updated_value = [existing_value, new_value].filter(Boolean).join('\n');

                        frm.set_value(target_field, updated_value);
                        return frappe.db.set_value(frm.doctype, frm.docname, target_field, updated_value);
                    })
                    .then(function () {
                        return frm.reload_doc();
                    })
                    .then(function () {
                        frm.refresh_field(target_field);
                        console.log(`✅ Images saved in ${target_field}:`, uploaded_file_urls);
                    })
                    .catch(function (error) {
                        frappe.msgprint(__('Error: ') + error);
                    });
            }
        });
    }

    function wait_for_camera_modal_and_validate() {
        if (window.__tache_camera_validation_interval) {
            clearInterval(window.__tache_camera_validation_interval);
        }

        window.__tache_camera_validation_interval = setInterval(function () {
            const camera_modal = $('.modal').filter(function () {
                const modal_text = $(this).text();
                return modal_text.includes('Caméra') && modal_text.includes('Valider');
            }).last();

            if (!camera_modal.length) return;

            const validate_button = camera_modal.find("button:contains('Valider')");
            const total_captured_images = camera_modal.find("img[src*='data:image'], .file-preview img, .image-container img").length;

            console.log('🔹 Total Images Captured:', total_captured_images);

            validate_button.off('click.tache_photo_validation').on('click.tache_photo_validation', function (event) {
                const current_total = camera_modal.find("img[src*='data:image'], .file-preview img, .image-container img").length;

                if (current_total < 3) {
                    event.preventDefault();
                    event.stopImmediatePropagation();

                    if (!$('.frappe-msgprint').length) {
                        frappe.msgprint({
                            title: __('Erreur'),
                            indicator: 'red',
                            message: __('Vous devez capturer au moins 3 photos avant de valider.')
                        });
                    }

                    return false;
                }
            });

            camera_modal.off('hidden.bs.modal.tache_photo_validation').on('hidden.bs.modal.tache_photo_validation', function () {
                console.log('🔄 Modal closed. Restarting validation check.');
                wait_for_camera_modal_and_validate();
            });
        }, 500);
    }

    wait_for_camera_modal_and_validate();
})();

frappe.ui.form.on('Appelle Client', {
    a_été_appelé: function(frm, cdt, cdn) {
        // Assuming 'a_ete_appele' is the fieldname for a checkbox field in the child table
        // Assuming 'nb_appels_restants' is the fieldname for a field in the parent form
        // cdt and cdn are the child doctype and child docname, respectively

        // Get the child document using the cdt and cdn
        var appel = locals[cdt][cdn];

        // Check the value of 'a_ete_appele' field and update 'nb_appels_restants'
        recalculate_Nb_Appelle(frm, 'clients');
    },
    resume_appel: function(frm, cdt, cdn) {
        // Assuming 'a_ete_appele' is the fieldname for a checkbox field in the child table
        // Assuming 'nb_appels_restants' is the fieldname for a field in the parent form
        // cdt and cdn are the child doctype and child docname, respectively
        var appel = frappe.get_doc(cdt, cdn);

        refresh_field('clients'); 
        // Get the child document using the cdt and cdn
        recalculate_Nb_R(frm, 'clients')
        recalculate_Nb_Pr(frm, 'clients')
    },
    intéressé_par_le_service_dentretien: function(frm, cdt, cdn) {
        recalculate_Ent(frm, 'intéressé_par_le_service_dentretien','nb_c_n_e')
    },
    intéressé_par_le_service_de_relance: function(frm, cdt, cdn) {
        recalculate_Ent(frm, 'intéressé_par_le_service_de_relance','nb_c_n_r')
    },
});
function recalculate_Nb_Appelle(frm, child_table_name) {
    var NB_prg = 0; // Corrected 'Let' to 'var' for variable declaration

    // Iterate over each row in the child table
    $.each(frm.doc[child_table_name], function(index, row) {
        // Check if resume_appel is 'Rendez-vous pris' or 'Livraison prévue'
        if (row.a_été_appelé === 0 ) {
            NB_prg += 1; // Increment the count if the condition is met
        }
    });


    // Update the field on the form if needed
    // Replace 'fieldname_to_update' with the actual fieldname on the parent doctype
    frm.set_value('nb_appels_restant', NB_prg);

    // Refresh the field to update the display
    frm.refresh_field('nb_appels_restant');
}
function recalculate_Nb_Pr(frm, child_table_name) {
    var NB_prg = 0; // Corrected 'Let' to 'var' for variable declaration

    // Iterate over each row in the child table
    $.each(frm.doc[child_table_name], function(index, row) {
        // Check if resume_appel is 'Rendez-vous pris' or 'Livraison prévue'
        if (row.resume_appel === 'Rendez-vous pris' || row.resume_appel === 'Livraison prévue') {
            NB_prg += 1; // Increment the count if the condition is met
        }
    });


    // Update the field on the form if needed
    // Replace 'fieldname_to_update' with the actual fieldname on the parent doctype
    frm.set_value('nb_r_p', NB_prg);

    // Refresh the field to update the display
    frm.refresh_field('nb_r_p');
}
function recalculate_Nb_R(frm, child_table_name) {
    var NB_prg = 0; // Corrected 'Let' to 'var' for variable declaration

    // Iterate over each row in the child table
    $.each(frm.doc[child_table_name], function(index, row) {
        // Check if resume_appel is 'Rendez-vous pris' or 'Livraison prévue'
        if (row.resume_appel === 'Ne répond pas 1er appel') {
            NB_prg += 1; // Increment the count if the condition is met
        }
    });


    // Update the field on the form if needed
    // Replace 'fieldname_to_update' with the actual fieldname on the parent doctype
    frm.set_value('nb_2_r', NB_prg);

    // Refresh the field to update the display
    frm.refresh_field('nb_2_r');
}
function recalculate_Ent(frm, field, field1) {
    var NB_prg = 0; // Corrected 'Let' to 'var' for variable declaration

    // Iterate over each row in the child table
    $.each(frm.doc['clients'], function(index, row) {
        // Check if resume_appel is 'Rendez-vous pris' or 'Livraison prévue'
        if (row[field] === 'Non' ) {
            NB_prg += 1; // Increment the count if the condition is met
        }
    });


    // Update the field on the form if needed
    // Replace 'fieldname_to_update' with the actual fieldname on the parent doctype
    frm.set_value(field1, NB_prg);

    // Refresh the field to update the display
    frm.refresh_field(field1);
}

frappe.listview_settings["Liste Appelle Entretien"] = {
    onload(listview) {
        // ── Bouton "Générer listes d'appels" ──────────────────────────────
        listview.page.add_inner_button(
            __("Générer listes d'appels"),
            function () {
                frappe.prompt(
                    [
                        {
                            label: __("Type de génération"),
                            fieldname: "list_type",
                            fieldtype: "Select",
                            options: ["all", "normal", "relance", "urgence"],
                            default: "all"
                        }
                    ],
                    function (values) {
                        frappe.call({
                            method: "customization_app.Maintenance.creation_liste_appelle.run_manual",
                            args: { list_type: values.list_type },
                            freeze: true,
                            freeze_message: __("Génération des listes d'appels..."),
                            callback: function (r) {
                                if (!r.exc) {
                                    frappe.msgprint({
                                        title: __("Succès"),
                                        message: __("Génération terminée. Vérifiez les nouvelles listes."),
                                        indicator: "green"
                                    });
                                    // After generating, go to page 1 to see new lists
                                    listview.start = 0;
                                    listview.refresh();
                                }
                            }
                        });
                    },
                    __("Générer des listes d'appels"),
                    __("Lancer")
                );
            }
        );
    }
};

frappe.ui.form.on('Customer', {
    refresh(frm) {

        if (!frm.doc.name || frm.is_new()) {
            return;
        }

        // Clear previous headline alerts & indicateurs spécifiques
        frm.dashboard.clear_headline();
        $('.form-dashboard-section .row .indicator:contains("Facturation Annuelle")').remove();
        $('.form-dashboard-section .row .indicator:contains("Total des Impayés")').remove();

        // Buffers HTML pour tout afficher dans UN seul headline
        let rendezVousHtml = "";
        let ristourneHtml  = "";
        let verifHtml      = "";

        function update_headline() {
            if (!rendezVousHtml && !ristourneHtml && !verifHtml) return;

            const full_html = `
                <div>
                    ${verifHtml      || ""}
                    ${rendezVousHtml || ""}
                    ${ristourneHtml  || ""}
                </div>
            `;
            frm.dashboard.set_headline_alert(full_html, 'blue');
        }

        // Helpers numériques
        function num(v) {
            try {
                if (typeof flt === "function") {
                    return flt(v || 0);
                }
            } catch(e) {}
            const n = parseFloat(v || 0);
            return isNaN(n) ? 0 : n;
        }

        function almostEqual(a, b, tolerance = 50) {
            // Si les deux valeurs sont à zéro, considérer comme égales
            if (a === 0 && b === 0) return true;
            // Tolérance de 50 dinars par défaut
            return Math.abs(a - b) <= tolerance;
        }

        // --- 1) CALL EXISTANT : get_customer_info ---
        frappe.call({
            method: "get_customer_info",
            args: {
                customer_name: frm.doc.name
            },
            callback: function(r) {
                if (r.result) {
                    let final_result = r.result[0] || {};
                    let rendez_vous = r.result[1] || [];
                    let heatmapData = r.result[2];

                    // Indicateurs principaux
                    frm.dashboard.clear_headline();
                    frm.dashboard.add_indicator(
                        `Total des ventes: ${final_result['Total des ventes']} د.ت`,
                        'blue'
                    );
                    frm.dashboard.add_indicator(
                        `Total des paiements: ${final_result['Total des paiements']} د.ت`,
                        'green'
                    );

                    // --- Tous les types de paiement + remises + retenues + avances ---

                    if (final_result['Total des paiements en Espèces']) {
                        frm.dashboard.add_indicator(
                            `Paiements en Espèces: ${final_result['Total des paiements en Espèces']} د.ت`,
                            'orange'
                        );
                    }

                    if (final_result['Total des paiements par Virement']) {
                        frm.dashboard.add_indicator(
                            `Paiements par Virement: ${final_result['Total des paiements par Virement']} د.ت`,
                            'orange'
                        );
                    }

                    if (final_result['Total des paiements par Chèques encaissé']) {
                        frm.dashboard.add_indicator(
                            `Chèques encaissés: ${final_result['Total des paiements par Chèques encaissé']} د.ت`,
                            'purple'
                        );
                    }

                    if (final_result['Total des paiements par Chèques non encaissé']) {
                        frm.dashboard.add_indicator(
                            `Chèques non encaissés: ${final_result['Total des paiements par Chèques non encaissé']} د.ت`,
                            'red'
                        );
                    }

                    if (final_result['Total des paiements par Chèques sans provision']) {
                        frm.dashboard.add_indicator(
                            `Chèques sans provision: ${final_result['Total des paiements par Chèques sans provision']} د.ت`,
                            'brown'
                        );
                    }

                    if (final_result['Total des paiements par Traite Bancaire']) {
                        frm.dashboard.add_indicator(
                            `Traites bancaires: ${final_result['Total des paiements par Traite Bancaire']} د.ت`,
                            'cyan'
                        );
                    }

                    if (final_result['Total des retenues à la source']) {
                        frm.dashboard.add_indicator(
                            `Retenues à la source: ${final_result['Total des retenues à la source']} د.ت`,
                            'yellow'
                        );
                    }

                    if (final_result['Total des avances du client']) {
                        frm.dashboard.add_indicator(
                            `Avances du client: ${final_result['Total des avances du client']} د.ت`,
                            'yellow'
                        );
                    }

                    if (final_result['Total des remises sur commande']) {
                        frm.dashboard.add_indicator(
                            `Remises sur commande: ${final_result['Total des remises sur commande']} د.ت`,
                            'purple'
                        );
                    }

                    if (final_result['Total des dettes non payées']) {
                        frm.dashboard.add_indicator(
                            `Dettes non payées: ${final_result['Total des dettes non payées']} د.ت`,
                            'gray'
                        );
                    }

                    if (final_result['Total perte de non paiement']) {
                        frm.dashboard.add_indicator(
                            `Perte de non paiement: ${final_result['Total perte de non paiement']} د.ت`,
                            'red'
                        );
                    }

                    // --- Vérifications de cohérence des totaux ---

                    const t = final_result;

                    const totalVentes   = num(t["Total des ventes"]);
                    const totalPayts    = num(t["Total des paiements"]);
                    const totalRemises  = num(t["Total des remises sur commande"]);

                    const especes       = num(t["Total des paiements en Espèces"]);
                    const virement      = num(t["Total des paiements par Virement"]);
                    const chqEnc        = num(t["Total des paiements par Chèques encaissé"]);
                    const chqNon        = num(t["Total des paiements par Chèques non encaissé"]);
                    const chqSP         = num(t["Total des paiements par Chèques sans provision"]);
                    const traite        = num(t["Total des paiements par Traite Bancaire"]);
                    const retenues      = num(t["Total des retenues à la source"]);
                    const dettes        = num(t["Total des dettes non payées"]);
                    const pertes        = num(t["Total perte de non paiement"]);
                    const avancesClient = num(t["Total des avances du client"]);

                    // Tolérance acceptée pour les vérifications
                    const tolerance = 50; // 50 dinars

                    // Règle 1 : Total ventes = Total paiements + remises
                    const lhs1 = totalVentes;
                    const rhs1 = totalPayts + totalRemises;
                    const delta1 = Math.abs(lhs1 - rhs1);
                    const ok1  = almostEqual(lhs1, rhs1, tolerance);

                    // Règle 2 : Total paiements = somme des champs de paiement + dettes/pertes/avances
                    const breakdownSum =
                        especes +
                        virement +
                        chqEnc +
                        chqNon +
                        chqSP +
                        traite +
                        retenues +
                        dettes +
                        pertes +
                        avancesClient;

                    const delta2 = Math.abs(totalPayts - breakdownSum);
                    const ok2 = almostEqual(totalPayts, breakdownSum, tolerance);

                    verifHtml = "";

                    // Ne pas afficher d'alerte si tous les totaux sont à zéro
                    const allZero = (totalVentes === 0 && totalPayts === 0 && totalRemises === 0);

                    if (allZero) {
                        verifHtml = ""; // Pas d'alerte si tout est à zéro
                    } else if (!ok1 || !ok2) {
                        // 🔴 Cas incohérent : bloc rouge
                        verifHtml += `
                            <div style="
                                margin-bottom:8px;
                                padding:6px 8px;
                                border-radius:3px;
                                background:#fff1f0;
                                border:1px solid #ffa39e;
                                font-size:11px;
                                color:#a8071a;
                            ">
                                <b>⚠ Incohérence dans les totaux client :</b><br>
                                <small style="color:#8c8c8c;">(Tolérance acceptée : ${frappe.format(tolerance, {fieldtype:"Currency"})})</small><br>
                        `;

                        if (!ok1) {
                            verifHtml += `
                                • Total des ventes (${frappe.format(lhs1, {fieldtype:"Currency"})})
                                  ≠ Total des paiements + remises
                                  (${frappe.format(rhs1, {fieldtype:"Currency"})})<br>
                                  <small style="color:#cf1322;">→ Écart: ${frappe.format(delta1, {fieldtype:"Currency"})}</small><br>
                            `;
                        }

                        if (!ok2) {
                            verifHtml += `
                                • Total des paiements (${frappe.format(totalPayts, {fieldtype:"Currency"})})
                                  ≠ Somme des modes de paiement, dettes, pertes et avances
                                  (${frappe.format(breakdownSum, {fieldtype:"Currency"})})<br>
                                  <small style="color:#cf1322;">→ Écart: ${frappe.format(delta2, {fieldtype:"Currency"})}</small><br>
                            `;
                        }

                        verifHtml += `</div>`;
                    } else {
                        // ✅ Cas OK : bloc vert
                        verifHtml = `
                            <div style="
                                margin-bottom:8px;
                                padding:6px 8px;
                                border-radius:3px;
                                background:#f6ffed;
                                border:1px solid #b7eb8f;
                                font-size:11px;
                                color:#135200;
                            ">
                                <b>✓ Totaux cohérents :</b><br>
                                <small style="color:#8c8c8c;">(Tolérance acceptée : ${frappe.format(tolerance, {fieldtype:"Currency"})})</small><br>
                                • Total des ventes = Total des paiements + remises<br>
                                  <small style="color:#52c41a;">→ Écart: ${frappe.format(delta1, {fieldtype:"Currency"})}</small><br>
                                • Total des paiements = somme des modes de paiement, dettes, pertes et avances<br>
                                  <small style="color:#52c41a;">→ Écart: ${frappe.format(delta2, {fieldtype:"Currency"})}</small>
                            </div>
                        `;
                    }

                    // RDV en HTML (block jaune)
                    if (Array.isArray(rendez_vous) && rendez_vous.length > 0) {
                        const rendez_vous_details = rendez_vous.join('<br>');
                        rendezVousHtml = `
                            <div style="
                                margin-bottom:8px;
                                padding:8px;
                                background:#fffbe6;
                                border:1px solid #ffe58f;
                                border-radius:3px;
                                font-size:12px;
                            ">
                                <b>Prochains rendez-vous :</b><br>
                                ${rendez_vous_details}
                            </div>
                        `;
                    }

                    update_headline();

                    if (heatmapData) {
                        frm.dashboard.update_heatmap(heatmapData);
                    }
                }
            }
        });

        // --- 2) NOUVEAU CALL : RISTOURNE ---
        frappe.call({
            method: "customization_app.api.get_customer_ristourne_dashboard",
            args: {
                customer: frm.doc.name
            },
            callback: function(r) {
                if (!r.message) return;

