frappe.ui.form.on('Tache de travail', {

    onload: function(frm) {
        // Always register address filter + change handler
        setup_address_filter(frm);

        if (!frm.is_new()) return;

        // ── Inside iframe (calendar overlay) ──
        if (window.top !== window.self) {
            let ctx = {};
            try {
                const raw = localStorage.getItem('rdv_prefill');
                if (raw) { ctx = JSON.parse(raw); localStorage.removeItem('rdv_prefill'); }
            } catch(e) {}
            const doc = Object.assign({}, ctx);
            delete doc.subject;
            if (frm.doc.starts_on) doc.starts_on = frm.doc.starts_on;
            if (frm.doc.ends_on)   doc.ends_on   = frm.doc.ends_on;
            window.parent.postMessage({ type: 'rdv_new_doc', doc: doc }, '*');
            setTimeout(function(){ window.history.back(); }, 80);
            return;
        }

        // ── Quick entry (parent page) ──
        // make_quick_entry sets fields AFTER onload, so poll until client is set
        let tries = 0;
        const t = setInterval(function(){
            if (frm.doc.custom_client) {
                clearInterval(t);
                setup_address_filter(frm); // re-apply now that client is known
            } else if (++tries > 25) { clearInterval(t); }
        }, 120);
    },

    select_address: function(frm) {
        fill_address_fields(frm);
    },

    custom_client: function(frm) {
        setup_address_filter(frm);
        frm.set_value('select_address', '');
        frm.set_value('details_adresse', '');
    }
});

function setup_address_filter(frm) {
    frm.set_query('select_address', function() {
        const client = frm.doc.custom_client;
        if (!client) return {};
        return {
            query: 'frappe.contacts.doctype.address.address.address_query',
            filters: { link_doctype: 'Customer', link_name: client }
        };
    });
}

function fill_address_fields(frm) {
    if (!frm.doc.select_address) {
        frm.set_value('details_adresse', '');
        frm.set_value('google_map', '');
        return;
    }
    frappe.db.get_value('Address', frm.doc.select_address, [
        'address_line1', 'address_line2', 'city', 'pincode',
        'state', 'country', 'custom_lien_google_map'
    ]).then(function(r) {
        const a = r.message || {};
        const lines = [a.address_line1, a.address_line2, a.city]
            .filter(Boolean);
        const region = [a.pincode, a.state, a.country].filter(Boolean).join(', ');
        if (region) lines.push(region);
        frm.set_value('details_adresse', lines.join('\n'));
        if (a.custom_lien_google_map) frm.set_value('google_map', a.custom_lien_google_map);
    });
}

/* ── Aide contextuelle (economiq only) ────────────────────────────────────── */
function _econo_help(storageKey, title, items) {
    if (frappe.session.user !== 'economiqaquasolutions23@gmail.com') return $();
    if (localStorage.getItem(storageKey) === 'hidden') return $();
    var $existing = $('#' + storageKey);
    if ($existing.length) return $existing;
    var collapsed = localStorage.getItem(storageKey + '_c') === '1';
    var html = items.map(function(it) {
        return "<div style='display:flex;gap:8px;align-items:flex-start;margin:3px 0;'><span style='font-size:14px;flex-shrink:0;'>" + it.icon + "</span><span style='font-size:12px;color:#444;line-height:1.5;'><strong>" + it.label + "</strong>" + (it.desc ? ' — ' + it.desc : '') + "</span></div>";
    }).join('');
    var $b = $("<div id='" + storageKey + "' style='background:linear-gradient(135deg,#e8f5fd,#f0f9ff);border:1px solid #90caf9;border-radius:10px;padding:10px 14px;margin-bottom:12px;box-shadow:0 2px 6px rgba(0,100,200,0.08);'><div style='display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;'><strong style='font-size:12px;color:#1565c0;'>💡 " + title + "</strong><div style='display:flex;gap:12px;'><button class='_ht' style='font-size:11px;color:#1565c0;background:none;border:none;cursor:pointer;padding:0;'>" + (collapsed ? '▶ Afficher' : '▼ Réduire') + "</button><button class='_hc' style='font-size:11px;color:#aaa;background:none;border:none;cursor:pointer;padding:0;'>✕ Fermer</button></div></div><div class='_hb' style='display:" + (collapsed ? "none" : "block") + ";'>" + html + "</div></div>");
    $b.find('._ht').on('click', function() { var $bd = $b.find('._hb'); var v = $bd.is(':visible'); $bd.toggle(); $(this).text(v ? '▶ Afficher' : '▼ Réduire'); localStorage.setItem(storageKey + '_c', v ? '1' : '0'); });
    $b.find('._hc').on('click', function() { localStorage.setItem(storageKey, 'hidden'); $b.fadeOut(200, function() { $b.remove(); }); });
    return $b;
}


