/* ─── STATISTICS BANNER ─────────────────────────────────────────────────── */
function render_stats_banner(frm) {
    // Remove previous banner
    frm.$wrapper.find('.lae-stats-banner').remove();

    const d = frm.doc;
    const total = (d.clients || []).length;
    const appelés = (d.clients || []).filter(r => r['a_été_appelé']).length;
    const restant = parseInt(d.nb_appels_restant) || 0;
    const rdv_prog = parseInt(d.nb_r_p) || 0;
    const rdv_cal  = parseInt(d.nb_r_c) || 0;
    const non_ent  = parseInt(d.nb_c_n_e) || 0;
    const non_rel  = parseInt(d.nb_c_n_r) || 0;
    const rappeler = parseInt(d.nb_2_r) || 0;
    const pct = total ? Math.round((appelés / total) * 100) : 0;

    const STATS = [
        { icon:'📞', label:'Appels restants',       val: restant,  color:'#e53935', bg:'#ffebee' },
        { icon:'📅', label:'RDV / Liv. programmés', val: rdv_prog, color:'#1565c0', bg:'#e3f2fd' },
        { icon:'🗓️', label:'RDV / Liv. calendrier', val: rdv_cal,  color:'#00796b', bg:'#e0f2f1' },
        { icon:'🔁', label:'À rappeler 2ème fois',  val: rappeler, color:'#f57f17', bg:'#fff8e1' },
        { icon:'❄️', label:'Non intéressé entretien', val: non_ent, color:'#6a1b9a', bg:'#f3e5f5' },
        { icon:'📵', label:'Non intéressé relance',  val: non_rel, color:'#37474f', bg:'#eceff1' },
    ];

    const cards_html = STATS.map(s =>
        `<div style="background:${s.bg};border-radius:10px;padding:12px 18px;display:flex;
            flex-direction:column;align-items:center;min-width:130px;flex:1;box-shadow:0 1px 4px rgba(0,0,0,0.08);border-top:3px solid ${s.color};">
            <span style="font-size:22px;line-height:1;">${s.icon}</span>
            <span style="font-size:26px;font-weight:800;color:${s.color};margin-top:4px;">${s.val}</span>
            <span style="font-size:11px;color:#666;text-align:center;margin-top:3px;line-height:1.3;">${s.label}</span>
        </div>`
    ).join('');

    const bar_color = pct >= 80 ? '#4caf50' : pct >= 40 ? '#fbc02d' : '#e53935';
    const banner = $(`
        <div class="lae-stats-banner" style="margin:12px 0 18px;padding:16px 18px;
            background:#fff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.10);border:1px solid #e8ecf0;">

            <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;flex-wrap:wrap;gap:8px;">
                <div style="display:flex;align-items:center;gap:10px;">
                    <span style="font-size:15px;font-weight:700;color:#333;">
                        📋 ${d.titre || (d.type_liste + ' — ' + (d.date || ''))}
                    </span>
                    ${d.type_liste ? `<span style="background:${d.type_liste==='Urgence'?'#ffebee':d.type_liste==='Normal'?'#e3f2fd':'#e8f5e9'};
                        color:${d.type_liste==='Urgence'?'#c62828':d.type_liste==='Normal'?'#1565c0':'#2e7d32'};
                        font-size:11px;font-weight:700;padding:2px 10px;border-radius:20px;">${d.type_liste}</span>` : ''}
                </div>
                <div style="display:flex;align-items:center;gap:8px;">
                    <span style="font-size:12px;color:#888;">${appelés} / ${total} appelés</span>
                    <div style="width:120px;height:10px;background:#f0f0f0;border-radius:10px;overflow:hidden;">
                        <div style="width:${pct}%;height:100%;background:${bar_color};border-radius:10px;transition:width 0.4s;"></div>
                    </div>
                    <span style="font-size:12px;font-weight:700;color:${bar_color};">${pct}%</span>
                </div>
            </div>

            <div style="display:flex;gap:10px;flex-wrap:wrap;">
                ${cards_html}
            </div>
        </div>
    `);

    // Insert right after the form's layout div (top of the form body)
    const $form_body = frm.$wrapper.find('.form-layout').first();
    $form_body.prepend(banner);
}

/* ─── STYLE MAP ─────────────────────────────────────────────────────────── */
// Card color depends on whether the client has been called, then on résumé.
// Not called → gray  (regardless of résumé)
// Called:
//   Rendez-vous pris / Livraison prévue          → light green
//   Ne répond pas 1er / 2ième appel               → light yellow
//   Il va passer au magasin / Autres reponses     → light magenta
//   Fait lui-même                                 → light blue
//   Il n'y a pas de système de traitement installé → light red
const RESUME_STYLES = {
    'Rendez-vous pris':          { bg:'#e8f5e9', left:'#4caf50', text:'#1b5e20' },
    'Livraison prévue':          { bg:'#e8f5e9', left:'#4caf50', text:'#1b5e20' },
    'Ne répond pas 1er appel':   { bg:'#fffde7', left:'#f9a825', text:'#795900' },
    'Ne répond pas 2ieme appel': { bg:'#fffde7', left:'#f9a825', text:'#795900' },
    'Fait lui-même':             { bg:'#e3f2fd', left:'#1e88e5', text:'#0d47a1' },
    'Il va passer au magasin':   { bg:'#fce4ec', left:'#d81b60', text:'#880e4f' },
    "Il n\'y a pas de système de traitement installé":
                                 { bg:'#ffebee', left:'#e53935', text:'#b71c1c' },
    'Autres reponses':           { bg:'#fce4ec', left:'#d81b60', text:'#880e4f' },
};
const DS_APPELÉ = { bg:'#f5f5f5', left:'#bdbdbd', text:'#424242' }; // not yet called → gray
const RESUME_OPTIONS_ALL = ['','Ne répond pas 1er appel','Ne répond pas 2ieme appel',
    'Fait lui-même','Il va passer au magasin','Rendez-vous pris','Livraison prévue',
    "Il n\'y a pas de système de traitement installé",'Autres reponses'];
function get_resume_options(type_liste) {
    if (type_liste === 'Relance') {
        return RESUME_OPTIONS_ALL.filter(o => o !== 'Ne répond pas 1er appel');
    } else {
        return RESUME_OPTIONS_ALL.filter(o => o !== 'Ne répond pas 2ieme appel');
    }
}
const OUI_NON = ['','Oui','Non'];

function gs(r, appelé){ return appelé ? (RESUME_STYLES[r] || DS_APPELÉ) : DS_APPELÉ; }

/* ─── HELPERS ───────────────────────────────────────────────────────────── */
function field_row(label, val) {
    if (val===null||val===undefined||val==='') return '';
    return "<div style='display:flex;gap:6px;margin-top:4px;'>" +
        "<span style='color:#888;font-size:11px;min-width:110px;flex-shrink:0;'>" + label + " :</span>" +
        "<span style='font-size:11px;'>" + val + "</span></div>";
}
function make_select(cdn, fn, opts, cur, xs, bg) {
    return "<select class='inline-select form-control input-xs' data-cdn='"+cdn+"' data-field='"+fn+"' " +
        "style='font-size:11px;height:24px;padding:0 4px;border-radius:4px;min-width:160px;"+(bg?'background:'+bg+';':'')+(xs||'')+"'>" +
        opts.map(o=>"<option value='"+(o||'').replace(/'/g,"&#39;")+"'"+(o===cur?" selected":"")+">"+(o||'— choisir —')+"</option>").join('') +
        "</select>";
}
function make_check(cdn, fn, chk) {
    return "<input type='checkbox' class='inline-check' data-cdn='"+cdn+"' data-field='"+fn+"' "+(chk?"checked":"")+
        " style='width:16px;height:16px;cursor:pointer;accent-color:#4caf50;'>";
}

/* ─── CARDS ─────────────────────────────────────────────────────────────── */
function render_appelle_cards(frm) {
    const field = frm.fields_dict.clients;
    if (!field) return;
    const $w = field.$wrapper;
    $w.find('.grid-body').hide();

    const rows = frm.doc.clients || [];

    // Clean up if no rows
    if (!rows.length) {
        $w.find('.lae-filter-bar').remove();
        $w.find('.appelle-cards-container').remove();
        return;
    }

    /* ── Filter bar (created once) ──────────────────────────────────────── */
    let $filterBar = $w.find('.lae-filter-bar');
    if (!$filterBar.length) {
        const secteurs = [...new Set(rows.map(r => r.secteur || '').filter(Boolean))].sort();
        $filterBar = $(`
            <div class="lae-filter-bar" style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;
                padding:10px 12px;margin:6px 0 2px;background:#f8f9fa;border-radius:8px;border:1px solid #e4e7ea;">
                <span style="font-size:12px;font-weight:600;color:#555;white-space:nowrap;">🔍 Filtrer :</span>

                <select class="lae-f form-control input-sm" data-f="resume"
                    style="width:auto;min-width:165px;font-size:12px;height:30px;padding:0 6px;">
                    <option value="">— Tous les résumés —</option>
                    ${get_resume_options(frm.doc.type_liste)
                      .filter(o => o !== '')
                      .map(o=>`<option value="${o}">${o}</option>`).join('')}
                </select>

                <select class="lae-f form-control input-sm" data-f="appele"
                    style="width:auto;min-width:130px;font-size:12px;height:30px;padding:0 6px;">
                    <option value="">— Appelé / Non —</option>
                    <option value="1">✅ Appelé</option>
                    <option value="0">📞 À appeler</option>
                </select>

                ${secteurs.length ? `
                <select class="lae-f form-control input-sm" data-f="secteur"
                    style="width:auto;min-width:120px;font-size:12px;height:30px;padding:0 6px;">
                    <option value="">— Tous secteurs —</option>
                    ${secteurs.map(s=>`<option value="${s}">${s}</option>`).join('')}
                </select>` : ''}

                <input class="lae-f-search form-control input-sm" type="text"
                    placeholder="🔎 Recherche client / tél…"
                    style="width:165px;font-size:12px;height:30px;padding:0 8px;">

                <span class="lae-f-count" style="font-size:11px;color:#777;margin-left:4px;"></span>

                <button class="btn btn-xs btn-default lae-f-reset" style="margin-left:auto;font-size:11px;">
                    ✖ Réinitialiser
                </button>
            </div>
        `);
        $w.find('.grid-body').after($filterBar);
    }

    /* ── Cards container (created once, events via delegation) ─────────── */
    let $container = $w.find('.appelle-cards-container');
    if (!$container.length) {
        $container = $("<div class='appelle-cards-container' style='margin-top:6px;'></div>");

        /* ── DELEGATED EVENTS ─────────────────────────────────────────── */
        $container.on('click', '.open-client', function(e) {
            e.preventDefault();
            const c = $(this).data('client');
            if (c) frappe.set_route('Form', 'Customer', c);
        });
        $container.on('click', '.open-ech', function(e) {
            e.preventDefault();
            const ec = $(this).data('ech');
            if (ec) frappe.set_route('Form', 'Maintenance Schedule', ec);
        });
        $container.on('change', '.inline-select', function() {
            const cdn = $(this).data('cdn'), fn = $(this).data('field'), val = $(this).val();
            const NO_SYSTEM = "Il n'y a pas de système de traitement installé";
            frappe.model.set_value('Appelle Client', cdn, fn, val);
            // Live background update for entretien/relance dropdowns
            if (fn === 'intéressé_par_le_service_dentretien' || fn === 'intéressé_par_le_service_de_relance') {
                $(this).css('background', val === 'Non' ? '#ffcdd2' : '');
            }
            if (fn === 'resume_appel') {
                const row = (frm.doc.clients || []).find(r => r.name === cdn);
                if (row && row['a_été_appelé']) {
                    if (val === NO_SYSTEM) {
                        // Auto-set to Non when no water treatment system
                        frappe.model.set_value('Appelle Client', cdn, 'intéressé_par_le_service_dentretien', 'Non');
                        frappe.model.set_value('Appelle Client', cdn, 'intéressé_par_le_service_de_relance',  'Non');
                        render_appelle_cards(frm);
                    } else if (row.resume_appel === NO_SYSTEM || frm._prev_resume_was_no_system && frm._prev_resume_was_no_system[cdn]) {
                        // Changing away from "no system" → restore from Customer DB
                        const client = row.client;
                        if (client) {
                            frappe.db.get_value('Customer', client, [
                                'custom_intéressé_par_le_service_entretien',
                                'custom_envoi_sms'
                            ]).then(function(r) {
                                const v = r.message || {};
                                frappe.model.set_value('Appelle Client', cdn, 'intéressé_par_le_service_dentretien', v.custom_intéressé_par_le_service_entretien || '');
                                frappe.model.set_value('Appelle Client', cdn, 'intéressé_par_le_service_de_relance',  v.custom_envoi_sms || '');
                                if (!frm._prev_resume_was_no_system) frm._prev_resume_was_no_system = {};
                                delete frm._prev_resume_was_no_system[cdn];
                                render_appelle_cards(frm);
                            });
                        } else {
                            render_appelle_cards(frm);
                        }
                    } else {
                        render_appelle_cards(frm);
                    }
                } else {
                    render_appelle_cards(frm);
                }
                // Track if current value is NO_SYSTEM so we know on next change
                if (!frm._prev_resume_was_no_system) frm._prev_resume_was_no_system = {};
                frm._prev_resume_was_no_system[cdn] = (val === NO_SYSTEM);
            }
        });
        $container.on('change', '.inline-check', function() {
            const cdn = $(this).data('cdn'), fn = $(this).data('field'), val = $(this).is(':checked') ? 1 : 0;
            const NO_SYSTEM = "Il n'y a pas de système de traitement installé";
            frappe.model.set_value('Appelle Client', cdn, fn, val);
            $(this).siblings('span').css('color', val ? '#2e7d32' : '#c62828').text(val ? '✅ Appelé' : '📞 À appeler');
            const row = (frm.doc.clients || []).find(r => r.name === cdn);
            if (row && row.resume_appel === NO_SYSTEM) {
                if (val === 1) {
                    // Checking appelé + no system → set Non
                    frappe.model.set_value('Appelle Client', cdn, 'intéressé_par_le_service_dentretien', 'Non');
                    frappe.model.set_value('Appelle Client', cdn, 'intéressé_par_le_service_de_relance',  'Non');
                    render_appelle_cards(frm);
                } else {
                    // Unchecking appelé + no system → restore from Customer DB
                    const client = row.client;
                    if (client) {
                        frappe.db.get_value('Customer', client, [
                            'custom_intéressé_par_le_service_entretien',
                            'custom_envoi_sms'
                        ]).then(function(r) {
                            const v = r.message || {};
                            frappe.model.set_value('Appelle Client', cdn, 'intéressé_par_le_service_dentretien', v.custom_intéressé_par_le_service_entretien || '');
                            frappe.model.set_value('Appelle Client', cdn, 'intéressé_par_le_service_de_relance',  v.custom_envoi_sms || '');
                            render_appelle_cards(frm);
                        });
                    } else {
                        render_appelle_cards(frm);
                    }
                }
            } else {
                render_appelle_cards(frm);
            }
        });
        $container.on('click', '.create-rdv-btn', function() {
            localStorage.setItem('rdv_cdn', $(this).closest('[data-cdn]').data('cdn') || '');
            const editTask = $(this).data('tache') || '';
            const _self = this;

        function openOverlay(){
        // Full-screen fixed overlay — iframe sees 100vw×100vh like a real window
        // so FullCalendar calculates its height correctly
        $('#rdv-cal-overlay').remove(); // cleanup any previous

        // ── postMessage listener: iframe → open RDV custom dialog ──
        function rdvMsgHandler(ev){
            if (!ev.data || ev.data.type !== 'rdv_new_doc') return;
            window.removeEventListener('message', rdvMsgHandler);
            const d            = ev.data.doc;
            const cli          = d.custom_client || '';
            const rowCdn       = localStorage.getItem('rdv_cdn') || '';
            const editTaskName = localStorage.getItem('rdv_edit_task') || '';
            localStorage.removeItem('rdv_cdn');
            localStorage.removeItem('rdv_edit_task');
            $('#rdv-cal-overlay').remove();
            setTimeout(function(){
                var dlg;
                dlg = new frappe.ui.Dialog({
                    title: '\u{1F4C5} Nouveau Rendez-vous' + (cli ? ' \u2014 ' + cli : ''),
                    fields: [
                        {
                            fieldname: 'custom_client',
                            fieldtype: 'Link',
                            label: 'Client',
                            options: 'Customer',
                            read_only: 1,
                        },
                        { fieldtype: 'Column Break' },
                        {
                            fieldname: 'custom_type_dintervention',
                            fieldtype: 'Select',
                            label: "Type d'Intervention",
                            options: 'Entretien\nInstallation\nR\u00e9paration\nLivraison\nVisite\nAutre',
                            reqd: 1,
                        },
                        { fieldtype: 'Section Break' },
                        {
                            fieldname: 'custom_choix_du_staff',
                            fieldtype: 'Link',
                            label: 'Choix du Staff',
                            options: 'Employee',
                            reqd: 1,
                        },
                        { fieldtype: 'Column Break' },
                        {
                            fieldname: 'starts_on',
                            fieldtype: 'Datetime',
                            label: 'Commence le',
                            reqd: 1,
                        },
                        { fieldtype: 'Section Break' },
                        {
                            fieldname: 'secteur',
                            fieldtype: 'Data',
                            label: 'Secteur',
                            read_only: 1,
                        },
                        {
                            fieldname: 'select_address',
                            fieldtype: 'Link',
                            label: 'Adresse',
                            options: 'Address',
                            get_query: function(){
                                return {
                                    query: 'frappe.contacts.doctype.address.address.address_query',
                                    filters: { link_doctype: 'Customer', link_name: cli }
                                };
                            },
                            onchange: function(){
                                var addr = dlg.get_value('select_address');
                                if (!addr){ dlg.set_value('details_adresse',''); return; }
                                frappe.db.get_value('Address', addr,
                                    ['address_line1','address_line2','city','pincode','state','country']
                                ).then(function(r){
                                    var a = r.message || {};
                                    var lines = [a.address_line1,a.address_line2,a.city].filter(Boolean);
                                    var reg = [a.pincode,a.state,a.country].filter(Boolean).join(', ');
                                    if (reg) lines.push(reg);
                                    var full = (d.secteur ? 'Secteur: ' + d.secteur + '\n' : '') + lines.join('\n');
                                    dlg.set_value('details_adresse', full);
                                });
                            },
                        },
                        {
                            fieldname: 'details_adresse',
                            fieldtype: 'Small Text',
                            label: 'D\u00e9tails adresse',
                            read_only: 1,
                        },
                        { fieldtype: 'Section Break' },
                        {
                            fieldname: 'note',
                            fieldtype: 'Small Text',
                            label: 'Note',
                        },
                    ],
                    primary_action_label: 'Enregistrer le RDV',
                    primary_action: function(vals){
                        var STAFF_COLORS = {
                            'HR-EMP-00001': '#449CF0',
                            'HR-EMP-00002': '#ECAD4B',
                            'HR-EMP-00003': '#AA00AA',
                            'HR-EMP-00004': '#761ACB',
                            'HR-EMP-00005': '#CB2929',
                            'HR-EMP-00006': '#ED6396',
                            'HR-EMP-00007': '#888c89',
                            'HR-EMP-00008': '#37fab2',
                            'HR-EMP-00009': '#e6f542'
                        };
                        var INTERVENTION_ICONS = {
                            'Entretien':    '\uD83D\uDD27 ',
                            'Installation': '\uD83D\uDD28 ',
                            'R\u00e9paration': '\uD83E\uDDF0 ',
                            'Livraison':    '\uD83D\uDE90 ',
                            'Visite':       '\uD83D\uDE97 ',
                            'Autre':        '\u2615 '
                        };
                        var INTERVENTION_DURATIONS = {
                            'Entretien': 45, 'Installation': 105,
                            'R\u00e9paration': 120, 'Livraison': 30,
                            'Visite': 120, 'Autre': 120
                        };
                        var type_int  = vals.custom_type_dintervention || '';
                        var staffId   = vals.custom_choix_du_staff || '';
                        var color     = STAFF_COLORS[staffId] || '#888c89';
                        var icon      = INTERVENTION_ICONS[type_int] || '\u2615 ';
                        var secteur   = '';  // not available in dialog

                        // Compute ends_on from starts_on + duration if not passed
                        var starts    = vals.starts_on || '';
                        var ends      = d.ends_on || '';
                        if (starts && !ends) {
                            var dur = INTERVENTION_DURATIONS[type_int] || 120;
                            var m = new Date(starts.replace(' ','T'));
                            m.setMinutes(m.getMinutes() + dur);
                            var pad = function(n){ return String(n).padStart(2,'0'); };
                            ends = m.getFullYear()+'-'+pad(m.getMonth()+1)+'-'+pad(m.getDate())
                                  +' '+pad(m.getHours())+':'+pad(m.getMinutes())+':00';
                        }

                        // Fetch employee name then save
                        function doSave(employeeName) {
                            var sec = vals.secteur || d.secteur || '';
                            var titre = (sec ? sec + '\n' : '') + icon + type_int + ': Client: ' + (vals.custom_client || cli)
                                      + '\n' + (employeeName || '');
                            var doc = {
                                doctype:                   'Tache de travail',
                                custom_client:             vals.custom_client || cli,
                                custom_type_dintervention: type_int,
                                custom_choix_du_staff:     staffId,
                                custom_employ\u00e9:        employeeName || '',
                                starts_on:                 starts,
                                ends_on:                   ends,
                                select_address:            vals.select_address,
                                details_adresse:           vals.details_adresse || '',
                                secteur:                   vals.secteur || d.secteur || '',
                                subject:                   vals.note || '',
                                color:                     color,
                                titre:                     titre,
                            };
                            dlg.hide();
                            frappe.call({
                                method: 'frappe.client.save',
                                args: { doc: doc },
                            callback: function(r){
                                if (r.message){
                                    frappe.show_alert({message: 'Rendez-vous cr\u00e9\u00e9', indicator: 'green'}, 4);
                                    // Link task + set resume_appel → Rendez-vous pris
                                    var _newName = r.message.name;
                                    var _oldName = editTaskName;
                                    if (rowCdn) {
                                        frappe.model.set_value('Appelle Client', rowCdn, 'tache_de_travail', _newName);
                                        frappe.model.set_value('Appelle Client', rowCdn, 'resume_appel', 'Rendez-vous pris');
                                        frm.save().then(function(){
                                            render_appelle_cards(frm);
                                            // Delete old task AFTER parent saved
                                            if (_oldName) {
                                                frappe.call({
                                                    method: 'frappe.client.delete',
                                                    args: { doctype: 'Tache de travail', name: _oldName },
                                                    callback: function(){
                                                        frappe.show_alert({message: 'Ancien RDV supprimé', indicator: 'orange'}, 3);
                                                    }
                                                });
                                            }
                                        });
                                    } else if (_oldName) {
                                        frappe.call({ method: 'frappe.client.delete',
                                            args: { doctype: 'Tache de travail', name: _oldName } });
                                    }
                                }
                            }
                        });
                        } // end doSave

                        // Fetch employee name async, then save
                        if (staffId) {
                            frappe.db.get_value('Employee', staffId, 'employee_name')
                                .then(function(r){ doSave(r.message && r.message.employee_name || ''); });
                        } else {
                            doSave('');
                        }
                    },
                });
                // Pre-fill values after dialog created
                dlg.set_value('custom_client', cli);
                dlg.set_value('custom_type_dintervention', d.custom_type_dintervention || 'Entretien');
                if (d.custom_choix_du_staff) dlg.set_value('custom_choix_du_staff', d.custom_choix_du_staff);
                if (d.starts_on) dlg.set_value('starts_on', d.starts_on);
                dlg.set_value('secteur', d.secteur || '');
                dlg.show();
            }, 80);
        }
        window.addEventListener('message', rdvMsgHandler);

        const overlay = $('<div id="rdv-cal-overlay">').css({
            position:   'fixed',
            top: 0, left: 0, right: 0, bottom: 0,
            zIndex:     10000,
            background: '#fff',
            display:    'flex',
            flexDirection: 'column',
        });

        const clientLabel = (JSON.parse(localStorage.getItem('rdv_prefill') || '{}')).custom_client || '';
        var _isEditMode = !!localStorage.getItem('rdv_edit_task');
        const hdr = $('<div>').css({
            display:      'flex',
            alignItems:   'center',
            padding:      '6px 14px',
            background:   '#f5f7fa',
            borderBottom: '1px solid #d1d8dd',
            flexShrink:   0,
            gap:          '10px',
        }).append(
            $('<span>').css({ flex:'1', fontWeight:'600', fontSize:'14px' })
                .html('&#128197; Prendre Rendez-vous' + (clientLabel ? ' &mdash; <span style="color:#2490ef">'+clientLabel+'</span>' : '')),
            $('<button class="btn btn-sm btn-default">').html('&#8592; Revenir à la liste d&#39;appelle')
                .on('click', function(){
                    window.removeEventListener('message', rdvMsgHandler);
                    overlay.remove();
                    // Restore original color/titre if we were in edit mode
                    var editTaskName = localStorage.getItem('rdv_edit_task') || '';
                    var origRaw = localStorage.getItem('rdv_edit_original');
                    localStorage.removeItem('rdv_edit_task');
                    localStorage.removeItem('rdv_edit_original');
                    localStorage.removeItem('rdv_prefill');
                    if (editTaskName && origRaw) {
                        try {
                            var orig = JSON.parse(origRaw);
                            frappe.db.set_value('Tache de travail', editTaskName, {
                                color: orig.color || '',
                                titre: orig.titre || ''
                            });
                        } catch(e) {}
                    }
                })
        );

        // Tip banner for edit mode
        var tipBar = _isEditMode
            ? $('<div>').css({
                padding:    '8px 16px',
                background: '#fff3cd',
                borderBottom: '1px solid #ffc107',
                fontSize:   '12px',
                color:      '#856404',
                flexShrink: 0,
                display:    'flex',
                alignItems: 'center',
                gap:        '8px',
              }).html('<span style="font-size:16px">⚠️</span>'
                    + '<span><strong>Mode modification</strong> &mdash; '
                    + 'La tâche en <span style="color:#e53935;font-weight:700">rouge</span> est celle à modifier. '
                    + 'Cliquez ou glissez sur un nouveau créneau pour la déplacer.</span>')
            : null;

        const body = $('<div>').css({ flex:'1', overflow:'hidden', position:'relative' });

        const iframe = $('<iframe>').attr({
            src:         '/app/tache-de-travail/view/calendar/Calendrier%20de%20travail',
            frameborder: '0',
        }).css({ width:'100%', height:'100%', border:'none', display:'block' });

        // After load: hide Raven + week view + intercept new_doc → postMessage
        iframe.on('load', function(){
            try {
                const idoc = iframe[0].contentDocument;
                const iw   = iframe[0].contentWindow;
                if (!idoc) return;

                // Hide Raven
                if (!idoc.getElementById('rdv-s')) {
                    const s = idoc.createElement('style');
                    s.id = 'rdv-s';
                    s.textContent = '[class*="raven"],[id*="raven"]{display:none!important}';
                    idoc.head.appendChild(s);
                }

                // Intercept slot selection — belt+suspenders: both setOption AND new_event patch
                function patchCalendar(){
                    const calList = iw.cur_list;
                    if (!calList) return false;
                    if (calList._rdv_patched) return true;

                    function fmtDate(d){
                        if (!d) return '';
                        return d.getFullYear()+'-'+
                            String(d.getMonth()+1).padStart(2,'0')+'-'+
                            String(d.getDate()).padStart(2,'0')+' '+
                            String(d.getHours()).padStart(2,'0')+':'+
                            String(d.getMinutes()).padStart(2,'0')+':00';
                    }

                    function sendSlot(start, end){
                        const stored = JSON.parse(localStorage.getItem('rdv_prefill') || '{}');
                        const slot = {};
                        if (start) slot.starts_on = fmtDate(start);
                        if (end)   slot.ends_on   = fmtDate(end);
                        window.parent.postMessage({ type:'rdv_new_doc', doc: Object.assign({}, stored, slot) }, '*');
                    }

                    // 1. Patch calList.new_event (called by FullCalendar select callback)
                    if (typeof calList.new_event === 'function') {
                        calList.new_event = function(info){
                            sendSlot(info && info.start, info && info.end);
                        };
                    }

                    // 2. Also override via setOption on the FC instance
                    //    calList.calendar is the FullCalendar instance in Frappe v15
                    const fcCal = calList.calendar;
                    if (fcCal && typeof fcCal.setOption === 'function') {
                        fcCal.setOption('select', function(info){
                            sendSlot(info.start, info.end);
                        });
                        // 4. eventDrop: drag existing event → new slot (modifier mode)
                        fcCal.setOption('editable', true);
                        fcCal.setOption('eventDrop', function(info){
                            if (localStorage.getItem('rdv_edit_task')) {
                                var newStart = info.event.start;
                                var newEnd   = info.event.end || new Date(newStart.getTime() + 60*60*1000);
                                info.revert();
                                sendSlot(newStart, newEnd);
                            }
                        });
                        // 5. eventClick on the red task in modifier mode → use current times
                        fcCal.setOption('eventClick', function(info){
                            if (localStorage.getItem('rdv_edit_task')) {
                                var evStart = info.event.start;
                                var evEnd   = info.event.end || new Date(evStart.getTime() + 60*60*1000);
                                sendSlot(evStart, evEnd);
                            }
                        });
                    }

                    // 3. Patch frappe.new_doc on the iframe window as last resort
                    if (iw.frappe && iw.frappe.new_doc) {
                        const _orig = iw.frappe.new_doc;
                        iw.frappe.new_doc = function(doctype, opts, cb){
                            if (doctype === 'Tache de travail') {
                                const stored = JSON.parse(localStorage.getItem('rdv_prefill') || '{}');
                                sendSlot(opts && opts.starts_on ? null : null, null);
                                const merged = Object.assign({}, stored, opts || {});
                                window.parent.postMessage({ type:'rdv_new_doc', doc: merged }, '*');
                            } else {
                                _orig.call(iw.frappe, doctype, opts, cb);
                            }
                        };
                    }

                    calList._rdv_patched = true;

                    // Highlight handled by DB color set before overlay opens

                    return true;
                }

                // Click "Semaine" + patch calendar
                function clickSemaine(){
                    const jq = iw.jQuery || iw.$;
                    if (!jq) return false;
                    const btn = jq('button').filter(function(){
                        return jq(this).text().trim() === 'Semaine';
                    });
                    if (btn.length && !btn.hasClass('active')) { btn.trigger('click'); }
                    return btn.length > 0;
                }

                let tries = 0;
                const t = setInterval(function(){
                    const ok1 = clickSemaine();
                    const ok2 = patchCalendar();
                    if ((ok1 && ok2) || ++tries > 30) clearInterval(t);
                }, 200);

            } catch(e){ console.warn('rdv iframe load error', e); }
        });

        body.append(iframe);
        overlay.append(hdr);
        if (tipBar) overlay.append(tipBar);
        overlay.append(body);
        $('body').append(overlay);
        } // end openOverlay

        if (editTask) {
            localStorage.setItem('rdv_edit_task', editTask);
            // Get original values first, save them, then set red
            frappe.db.get_doc('Tache de travail', editTask).then(function(old_doc){
                // Save originals so we can revert if user cancels
                localStorage.setItem('rdv_edit_original', JSON.stringify({
                    color: old_doc.color || '',
                    titre: old_doc.titre || '',
                }));
                localStorage.setItem('rdv_prefill', JSON.stringify({
                    custom_client:             old_doc.custom_client || '',
                    custom_type_dintervention: old_doc.custom_type_dintervention || 'Entretien',
                    custom_choix_du_staff:     old_doc.custom_choix_du_staff || '',
                    select_address:            old_doc.select_address || '',
                    details_adresse:           old_doc.details_adresse || '',
                    secteur:                   old_doc.secteur || '',
                    note:                      old_doc.subject || '',
                }));
                // Now mark red in calendar
                frappe.db.set_value('Tache de travail', editTask, {
                    color: '#e53935',
                    titre: '🔴 Rendez-vous à modifier'
                }).then(function(){
                    openOverlay();
                }); // end set_value
            }); // end get_doc
        } else {
            localStorage.removeItem('rdv_edit_task');
            localStorage.setItem('rdv_prefill', JSON.stringify({
                custom_client:             $(_self).data('client') || '',
                tel:                       String($(_self).data('tel') || ''),
                details_adresse:           String($(_self).data('adresse') || ''),
                secteur:                   $(_self).data('secteur') || '',
                subject:                   String($(_self).data('info') || ''),
                custom_type_dintervention: 'Entretien',
            }));
            openOverlay();
        }
        });

        $filterBar.after($container);
    }

    /* ── Filter & render with pagination ───────────────────────────────── */
    const PAGE_SIZE = 15;
    // Persist current page in window state (keyed by docname) so DOM re-renders don't reset page
    if (!window._lae_page_state || window._lae_page_state.doc !== frm.docname) {
        window._lae_page_state = { doc: frm.docname, page: 1 };
    }
    let _currentPage = window._lae_page_state.page;

    function apply_filters(resetPage) {
        if (resetPage) _currentPage = 1;
        window._lae_page_state.page = _currentPage;
        const fResume  = $filterBar.find('[data-f="resume"]').val()  || '';
        const fAppele  = $filterBar.find('[data-f="appele"]').val()  || '';
        const fSecteur = $filterBar.find('[data-f="secteur"]').val() || '';
        const fSearch  = ($filterBar.find('.lae-f-search').val() || '').toLowerCase().trim();

        const visible = rows.filter(function(row) {
            if (fResume  && row.resume_appel !== fResume) return false;
            if (fAppele !== '' && String(row['a_été_appelé'] ? 1 : 0) !== fAppele) return false;
            if (fSecteur && (row.secteur || '') !== fSecteur) return false;
            if (fSearch  && !(row.client    || '').toLowerCase().includes(fSearch)
                         && !(row.secteur   || '').toLowerCase().includes(fSearch)
                         && !(row.telephone || '').toLowerCase().includes(fSearch)) return false;
            return true;
        });

        const totalPages = Math.max(1, Math.ceil(visible.length / PAGE_SIZE));
        if (_currentPage > totalPages) _currentPage = totalPages;
        const pageRows = visible.slice((_currentPage - 1) * PAGE_SIZE, _currentPage * PAGE_SIZE);

        let html = '';
        pageRows.forEach(function(row) {
            const s   = gs(row.resume_appel, row['a_été_appelé']);
            const cdn = row.name;
            const ech_link = row['échéancier_dentretien']
                ? "<a class='open-ech' href='#' data-ech='"+row['échéancier_dentretien']+"' style='color:#1565c0;text-decoration:underline dotted;'>"+row['échéancier_dentretien']+"</a>"
                : "—";
            const info_html = row.info
                ? "<div style='margin-top:8px;padding:7px 10px;background:rgba(0,0,0,0.04);border-radius:4px;font-size:11px;white-space:pre-line;color:#555;border-left:3px solid "+s.left+";'>"+row.info+"</div>"
                : '';
            const adresse_enc = (row.adresse||'').replace(/'/g,"&#39;").replace(/\n/g,', ');

            html +=
                "<div data-cdn='"+cdn+"' style='background:"+s.bg+";border-left:5px solid "+s.left+";border-radius:6px;padding:13px 16px;margin-bottom:10px;box-shadow:0 1px 4px rgba(0,0,0,0.08);'>" +

                "<div style='display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:10px;'>" +
                    "<div style='display:flex;align-items:center;gap:10px;flex-wrap:wrap;'>" +
                        "<a class='open-client' href='#' data-client='"+(row.client||'')+"' style='color:"+s.text+";text-decoration:underline dotted;font-size:14px;font-weight:700;'>👤 "+(row.client||'—')+"</a>" +
                        make_select(cdn,'resume_appel',get_resume_options(frm.doc.type_liste),row.resume_appel) +
                        "<label style='display:flex;align-items:center;gap:5px;font-size:11px;font-weight:600;cursor:pointer;'>" +
                            make_check(cdn,"a_été_appelé",row["a_été_appelé"]) +
                            "<span style='color:"+(row["a_été_appelé"]?'#2e7d32':'#c62828')+"'>"+(row["a_été_appelé"]?'✅ Appelé':'📞 À appeler')+"</span>" +
                        "</label>" +
                    "</div>" +
                    (row.tache_de_travail
                    ? "<button class='btn btn-xs btn-danger create-rdv-btn' "
                        + "data-tache='"+(row.tache_de_travail||'')+"' "
                        + "data-client='"+(row.client||'')+"' "
                        + "data-tel='"+(row.telephone||'')+"' "
                        + "data-adresse='"+adresse_enc+"' "
                        + "data-secteur='"+(row.secteur||'')+"' "
                        + "data-info='"+(row.info||'').replace(/'/g,"&#39;")+"' "
                        + ">✏️ Modifier rendez-vous</button>"
                    : "<button class='btn btn-xs btn-primary create-rdv-btn' "
                        + "data-client='"+(row.client||'')+"' "
                        + "data-tel='"+(row.telephone||'')+"' "
                        + "data-adresse='"+adresse_enc+"' "
                        + "data-secteur='"+(row.secteur||'')+"' "
                        + "data-info='"+(row.info||'').replace(/'/g,"&#39;")+"' "
                        + ">📅 Prendre Rendez-vous</button>"
                   ) +
                   (row.tache_de_travail
                    ? "<div style='margin-top:4px;text-align:right;'>"
                        + "<a href='/app/tache-de-travail/"+encodeURIComponent(row.tache_de_travail)+"' "
                        + "style='font-size:11px;color:#d32f2f;text-decoration:underline dotted;'>"
                        + "🔗 "+row.tache_de_travail+"</a></div>"
                    : '') +
                "</div>" +

                "<div style='display:grid;grid-template-columns:1fr 1fr;gap:2px 30px;'>" +
                    field_row('Échéancier', ech_link) +
                    field_row('Secteur',    row.secteur) +
                    field_row('Téléphone',  row.telephone) +
                    field_row('Adresse',    (row.adresse||'').replace(/\n/g,', ')) +
                    "<div style='display:flex;gap:6px;margin-top:4px;align-items:center;'><span style='color:#888;font-size:11px;min-width:110px;flex-shrink:0;'>Entretien :</span>" +
                        make_select(cdn,"intéressé_par_le_service_dentretien",OUI_NON,row["intéressé_par_le_service_dentretien"],"",row["intéressé_par_le_service_dentretien"]==="Non"?"#ffcdd2":"")+"</div>" +
                    "<div style='display:flex;gap:6px;margin-top:4px;align-items:center;'><span style='color:#888;font-size:11px;min-width:110px;flex-shrink:0;'>Relance :</span>" +
                        make_select(cdn,"intéressé_par_le_service_de_relance",OUI_NON,row["intéressé_par_le_service_de_relance"],"",row["intéressé_par_le_service_de_relance"]==="Non"?"#ffcdd2":"")+"</div>" +
                    field_row('Articles', row.detail_articles) +
                "</div>" +
                info_html + "</div>";
        });

        $container.html(html);

        // Counter
        $filterBar.find('.lae-f-count').text(
            visible.length === rows.length
                ? rows.length + ' clients'
                : visible.length + ' / ' + rows.length + ' clients'
        );

        // Pagination bar
        $w.find('.lae-pagination').remove();
        if (totalPages > 1) {
            const $pag = $('<div class="lae-pagination" style="display:flex;align-items:center;justify-content:center;gap:6px;padding:10px 4px 4px;flex-wrap:wrap;"></div>');

            function mkBtn(label, page, disabled, active) {
                const $b = $('<button class="btn btn-xs">').text(label)
                    .css({
                        minWidth: '32px',
                        fontWeight: active ? '700' : '400',
                        background: active ? '#2490ef' : '',
                        color: active ? '#fff' : '',
                        borderColor: active ? '#2490ef' : '',
                        opacity: disabled ? '0.4' : '1',
                        cursor: disabled ? 'default' : 'pointer',
                    });
                if (!disabled && !active) {
                    $b.on('click', function() { _currentPage = page; window._lae_page_state.page = page; apply_filters(); });
                }
                return $b;
            }

            $pag.append(mkBtn('‹', _currentPage - 1, _currentPage === 1, false));

            // Page buttons: show at most 7 around current page
            let start = Math.max(1, _currentPage - 3);
            let end   = Math.min(totalPages, _currentPage + 3);
            if (start > 1) $pag.append(mkBtn('1', 1, false, false)).append($('<span style="padding:0 2px;color:#aaa">…</span>'));
            for (let p = start; p <= end; p++) {
                $pag.append(mkBtn(String(p), p, false, p === _currentPage));
            }
            if (end < totalPages) $pag.append($('<span style="padding:0 2px;color:#aaa">…</span>')).append(mkBtn(String(totalPages), totalPages, false, false));

            $pag.append(mkBtn('›', _currentPage + 1, _currentPage === totalPages, false));

            // Page info
            const from = (_currentPage - 1) * PAGE_SIZE + 1;
            const to   = Math.min(_currentPage * PAGE_SIZE, visible.length);
            $pag.append($('<span style="font-size:11px;color:#888;margin-left:8px;">').text(from + '–' + to + ' sur ' + visible.length));

            $container.after($pag);
        }
    }

    /* ── Wire filter bar events (idempotent with namespace) ─────────────── */
    $filterBar
        .off('change.lae input.lae click.lae')
        .on('change.lae', '.lae-f', function() { apply_filters(true); })
        .on('input.lae', '.lae-f-search', function() { apply_filters(true); })
        .on('click.lae', '.lae-f-reset', function() {
            $filterBar.find('.lae-f').val('');
            $filterBar.find('.lae-f-search').val('');
            apply_filters(true);
        });

    // On render/re-render keep the current page; only filter changes reset to page 1
    apply_filters(false);
}
